/** Auto-generated for round 49 */
export const QUIZ_ITEMS = [
  { id: "1275", section: "الفتوحات الإسلامية", category: "المعارك", level: "متوسط", question: "ما معركة اليرموك؟", answer: "فتح عظيم في الشام هزم فيه المسلمون الروم في رجب سنة 15هـ في خلافة عمر بن الخطاب رضي الله عنه؛ أميرُ الجيش أبو عبيدة بن الجرّاح، وتولّى قيادة القتال خالد بن الوليد، وبها زال حكم الروم عن الشام", explanation: "يُستفاد منه في باب المعارك.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1276", section: "الفتوحات الإسلامية", category: "المعارك", level: "متوسط", question: "من قائد المسلمين في معركة القادسية؟", answer: "سعد بن أبي وقاص رضي الله عنه — كانت في شعبان سنة 15هـ في خلافة عمر بن الخطاب، وقائد الفرس فيها رستم وقُتل فيها، وكانت مفتاح فتح العراق", explanation: "يُستفاد منه في باب المعارك.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1277", section: "الفتوحات الإسلامية", category: "المعارك", level: "صعب", question: "ما معركة حطين وما أهميتها؟", answer: "معركة فاصلة في ربيع الآخر سنة 583هـ قادها صلاح الدين الأيوبي وهزم فيها الصليبيين هزيمة حطّمت قوّتهم في الشام، فاستُردّ بعدها بيت المقدس في رجب من السنة نفسها بعد نحو إحدى وتسعين سنة هجرية (88 سنة ميلادية) من احتلاله (وقع في أيديهم سنة 492هـ)", explanation: "يُستفاد منه في باب المعارك.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1278", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "سهل", question: "في أي عام فُتحت مكة المكرمة؟", answer: "في رمضان من السنة الثامنة للهجرة (8هـ/630م)، بعد أن نقضت قريش صلح الحديبية بإعانة حلفائها بني بكر على خزاعة حلفاء النبي ﷺ؛ ودخلها ﷺ من غير قتال عامّ إلا مناوشة يسيرة في ناحية خالد بن الوليد رضي الله عنه، وأمّن أهلها فقال: «اذهبوا فأنتم الطلقاء» (عند ابن هشام وأهل المغازي). وأكثر المفسرين على أن «الفتح» في قوله تعالى ﴿إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ﴾ [النصر: 1] هو فتح مكة", explanation: "يُستفاد منه في باب الفتوحات الإسلامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1279", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من قاد فتح القسطنطينية وفي أي عام؟", answer: "السلطان محمد الثاني العثماني الملقَّب بـ«الفاتح» يوم الثلاثاء العشرين من جمادى الأولى سنة 857هـ / التاسع والعشرين من مايو 1453م، فصارت القسطنطينية (إسطنبول) عاصمةَ الدولة بعد بورصة ثم أدرنة. ويربط كثير من أهل العلم هذا الفتح بحديث: «لتُفتحنّ القسطنطينية، فلنعم الأمير أميرها ولنعم الجيش ذلك الجيش» (رواه أحمد في المسند 18189، والبخاري في «التاريخ الكبير»)، وقد تكلّم بعض المحدّثين في إسناده", explanation: "يُستفاد منه في باب الفتوحات الإسلامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1280", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من فتح الشام في عهد أبي بكر الصديق ثم عمر بن الخطاب؟", answer: "بدأ الفتح بأمر أبي بكر الصدّيق رضي الله عنه، فوجّه إلى الشام أمراء منهم أبو عبيدة بن الجرّاح وعمرو بن العاص ويزيد بن أبي سفيان وشرحبيل بن حسنة رضي الله عنهم، وأمدّهم بخالد بن الوليد قادمًا من العراق. ثم كانت اليرموك في رجب سنة 15هـ في خلافة عمر بن الخطاب رضي الله عنه، وأميرُ الجيش يومئذ أبو عبيدة وقائدُ القتال خالد، وبها زال حكم الروم عن الشام، ثم فُتحت دمشق وبيت المقدس", explanation: "يُستفاد منه في باب الفتوحات الإسلامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1281", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من فتح مصر وفي أي عهد؟", answer: "عمرو بن العاص رضي الله عنه في خلافة عمر بن الخطاب رضي الله عنه؛ ولم يكن الفتح في سنة واحدة: دخل مصر سنة 19هـ، وسقط حصن بابليون سنة 20هـ/641م، ثم فُتحت الإسكندرية سنة 21هـ. واختطّ الفسطاط فكانت أول مدينة أسّسها المسلمون بمصر، وبها مسجده أول مسجد بُني في مصر", explanation: "يُستفاد منه في باب الفتوحات الإسلامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1282", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من قاد فتح الأندلس وفي أي عام؟", answer: "طارق بن زياد مولى موسى بن نصير والي إفريقية وبأمرٍ منه، عبر المضيق المعروف اليوم بمضيق جبل طارق سنة 92هـ/711م، وحُسم الأمر بهزيمة لُذريق ملك القوط في معركة وادي لكّة (شذونة)؛ ثم عبر موسى بن نصير في العام التالي بجيش آخر فأتمّا فتح ما بقي من المدن كإشبيلية وماردة", explanation: "يُستفاد منه في باب الفتوحات الإسلامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1283", section: "الفتوحات الإسلامية", category: "الغزوات", level: "سهل", question: "كم كان عدد المسلمين في غزوة بدر الكبرى؟", answer: "ثلاث مئة وبضعة عشر رجلًا؛ وهو الثابت في صحيح البخاري عن البراء بن عازب رضي الله عنه قال: «كنّا نتحدّث أنّ أصحاب بدر ثلاث مئة وبضعة عشر». وأمّا عدد المشركين فتقديرُ أهل السير والمغازي (كابن إسحاق) بنحو تسع مئة إلى ألف، وهو تقديرٌ منهم لا نصٌّ مرفوع. وكانت في السابع عشر من رمضان سنة 2هـ، وسمّى الله يومَها «يوم الفرقان»", explanation: "يُستفاد منه في باب الغزوات.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1284", section: "الفتوحات الإسلامية", category: "الغزوات", level: "سهل", question: "متى كانت غزوة أُحد؟", answer: "في شوّال من السنة الثالثة للهجرة (3هـ)؛ خرج النبي ﷺ في نحو ألف فرجع عبد الله بن أُبَيّ بثلث الجيش، والمشركون نحو ثلاثة آلاف. وكانت الدائرة للمسلمين أوّلًا ثم انقلبت لمّا ترك الرماة مواقعهم، واستُشهد نحو سبعين من المسلمين منهم حمزة بن عبد المطلب رضي الله عنه؛ قال تعالى: ﴿حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ﴾ [آل عمران: 152]", explanation: "يُستفاد منه في باب الغزوات.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1285", section: "الفتوحات الإسلامية", category: "الغزوات", level: "متوسط", question: "لماذا سُميت غزوة الأحزاب بالخندق؟", answer: "لأن المسلمين حفروا خندقًا حول المدينة يمنع المشركين من اقتحامها — وأصل حفر الخندق ثابت في الصحيحين، وأمّا تعيين سلمان الفارسي رضي الله عنه مشيرًا به فمن رواية أهل السِّيَر. وسُمّيت «الأحزاب» لتحزّب قبائل المشركين واليهود على المسلمين، وكانت في شوّال سنة 5هـ في نحو عشرة آلاف من الأحزاب، ولم يقع بين الجيشين التحامٌ عامّ لأن الخندق حال بينهما", explanation: "يُستفاد منه في باب الغزوات.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1286", section: "الفتوحات الإسلامية", category: "الفتوحات الإسلامية", level: "متوسط", question: "من قاد الجيوش الإسلامية لفتح فارس وما أشهر معاركه؟", answer: "سعد بن أبي وقاص رضي الله عنه، وأشهر معاركه القادسية سنة 15هـ على المشهور عند أهل السير وقيل 14هـ، ثم فتح المدائن عاصمة الفرس — أمّا معركة نهاوند (21هـ) التي سمّاها المؤرخون «فتح الفتوح» فقادها النعمان بن مقرن المزني رضي الله عنه (واستُشهد فيها) لا سعد", explanation: "يُستفاد منه في باب الفتوحات الإسلامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1287", section: "الفتوحات الإسلامية", category: "الغزوات", level: "صعب", question: "ما الحادثة التي نزل في مرجع النبي ﷺ منها قوله تعالى: ﴿إِنَّا فَتَحْنَا لَكَ فَتْحًۭا مُّبِينًۭا﴾؟", answer: "صلح الحديبية في ذي القعدة سنة 6هـ؛ ونزلت سورة الفتح وهو ﷺ راجعٌ منها بين مكة والمدينة لا في أثنائها، كما في حديث عمر بن الخطاب رضي الله عنه عند البخاري في كتاب المغازي (باب غزوة الحديبية). وهي معدودة عند أهل المغازي في مخارجه ﷺ ولم يقع فيها قتال، وسمّى الله الصلح فتحًا مبينًا لما أعقبه من الأمن ودخول الناس في الإسلام", explanation: "يُستفاد منه في باب الغزوات.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1288", section: "الفتوحات الإسلامية", category: "فتح مكة", level: "سهل", question: "في أي سنة فُتِحت مكة المكرمة؟", answer: "السنة الثامنة من الهجرة النبوية، في شهر رمضان — زمن فتح مكة المكرمة.", explanation: "يُستفاد منه في باب فتح مكة.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1289", section: "الفتوحات الإسلامية", category: "الفتوحات الشامية", level: "متوسط", question: "ما معركة اليرموك وما نتيجتها؟", answer: "معركة فاصلة عام 15 هجرية بين المسلمين والروم في الشام، انتصر فيها المسلمون وأفضت إلى فتح بلاد الشام", explanation: "يُستفاد منه في باب الفتوحات الشامية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1290", section: "الفتوحات الإسلامية", category: "الفتوحات الفارسية", level: "متوسط", question: "ما معركة نهاوند وما لقبها؟", answer: "معركة نهاوند عام 21 هجرية، سُميت فتح الفتوح لأنها الضربة القاضية على الإمبراطورية الساسانية", explanation: "يُستفاد منه في باب الفتوحات الفارسية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1291", section: "الفتوحات الإسلامية", category: "فتح مصر", level: "متوسط", question: "من قاد فتح مصر ومتى؟", answer: "عمرو بن العاص رضي الله عنه، عام 19-21 هجرية، وأسس الفسطاط عاصمةً للدولة الإسلامية في مصر", explanation: "يُستفاد منه في باب فتح مصر.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1292", section: "الفتوحات الإسلامية", category: "فتوح الشام", level: "متوسط", question: "ما معركة اليرموك وما أهميتها؟", answer: "معركة اليرموك (15هـ/ 636م): بين المسلمين بقيادة خالد بن الوليد وجيش الروم البيزنطي. انتصر فيها المسلمون نصراً ساحقاً فاتحاً لبلاد الشام كلها. تُعد من أكبر المعارك في التاريخ وأعظم فتوح الإسلام.", explanation: "يُستفاد منه في باب فتوح الشام.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1293", section: "الفتوحات الإسلامية", category: "فتوح العراق", level: "متوسط", question: "ما معركة القادسية ومن قائدها؟", answer: "معركة القادسية (14-15هـ/ 636م): بين المسلمين بقيادة سعد بن أبي وقاص والفرس الساسانيين. انتصر فيها المسلمون وفتحت العراق وأسقطت الإمبراطورية الساسانية. تُعد من أعظم الفتوح الإسلامية.", explanation: "يُستفاد منه في باب فتوح العراق.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1294", section: "الفتوحات الإسلامية", category: "فتوح مصر", level: "متوسط", question: "من فاتح مصر للإسلام وما العام الذي فُتحت فيه؟", answer: "عمرو بن العاص رضي الله عنه فتحها عام 20هـ (641م). كانت تحت سيطرة الرومان البيزنطيين. وبنى عمرو مدينة الفسطاط أول مدينة إسلامية في مصر، وبنى مسجد عمرو أول مسجد في أفريقيا.", explanation: "يُستفاد منه في باب فتوح مصر.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1295", section: "الفتوحات الإسلامية", category: "فتوح فارس", level: "متوسط", question: "ما المدائن وما أهميتها في الفتوحات الإسلامية؟", answer: "المدائن (Ctesiphon): عاصمة الفرس الساسانيين على نهر دجلة. فتحها سعد بن أبي وقاص عام 16هـ (637م). كانت من أعظم مدن العالم ومقر كسرى وملوك الفرس. فتحها أسقط الدولة الساسانية.", explanation: "يُستفاد منه في باب فتوح فارس.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1296", section: "الفتوحات الإسلامية", category: "فتوح المغرب", level: "متوسط", question: "من قاد فتح شمال أفريقيا (إفريقية) وبنى مدينة القيروان لتكون قاعدة الفتح الإسلامي هناك؟", answer: "عقبة بن نافع رضي الله عنه — بنى مدينة القيروان عام 50هـ (670م) لتكون قاعدة الفتح الإسلامي في المغرب. وامتد الفتح حتى المحيط الأطلسي قبل دخول الأندلس.", explanation: "يُستفاد منه في باب فتوح المغرب.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1297", section: "الفتوحات الإسلامية", category: "فتح مكة", level: "سهل", question: "في أي عام فُتحت مكة المكرمة؟ ومن أعلن أمان أهلها؟", answer: "فتحت مكة عام 8هـ (630م) في شهر رمضان. أعلن النبي ﷺ الأمان لأهل مكة قائلاً: «من دخل دار أبي سفيان فهو آمن، ومن أغلق بابه فهو آمن، ومن دخل المسجد فهو آمن» — وعفا عن أهلها جميعاً.", explanation: "يُستفاد منه في باب فتح مكة.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1298", section: "الفتوحات الإسلامية", category: "فتح فلسطين", level: "متوسط", question: "من الخليفة الذي تسلّم مفاتح بيت المقدس في الفتح الإسلامي الأول؟", answer: "عمر بن الخطاب رضي الله عنه — جاء بنفسه من المدينة عام 16هـ (638م) لتسلّم مفاتح القدس من بطريرك المدينة صفرونيوس (سوفرونيوس). وكتب العهدة العمرية ضامناً أمان أهل إيلياء.", explanation: "يُستفاد منه في باب فتح فلسطين.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1299", section: "الرقائق", category: "أخلاق المسلم", level: "سهل", question: "ما أعلى درجات اليقين التي ذكرها الله في القرآن؟", answer: "عين اليقين — ذكرت في سورة التكاثر. وحق اليقين — ذكرت في سورة الواقعة والحاقة. وعلم اليقين — في سورة التكاثر أيضاً.", explanation: "يُستفاد منه في باب أخلاق المسلم.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1300", section: "الرقائق", category: "آداب الكلام", level: "سهل", question: "ما حكم كثرة الكلام بلا فائدة في الإسلام؟", answer: "مكروه ومنهي عنه — قال ﷺ: «من صمت نجا» وقال: «إن من حسن إسلام المرء تركه ما لا يعنيه» — رواه الترمذي.", explanation: "يُستفاد منه في باب آداب الكلام.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1301", section: "الرقائق", category: "آداب المسجد", level: "سهل", question: "بأي رجل يُستحب الدخول للمسجد؟", answer: "بالرجل اليمنى — لحديث: «إذا دخل أحدكم المسجد فليبدأ بيمينه» ومثله الخروج يبدأ باليسرى.", explanation: "يُستفاد منه في باب آداب المسجد.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1302", section: "الرقائق", category: "الأخلاق الذميمة", level: "متوسط", question: "ما أكبر الكبائر التي حذّر منها النبي ﷺ؟", answer: "سُئل ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله، قال: «الإشراك بالله، وعقوق الوالدين» ثم جلس وقال: «ألا وقول الزور، وشهادة الزور» (متفق عليه — رواه البخاري ومسلم عن أبي بكرة)", explanation: "يُستفاد منه في باب الأخلاق الذميمة.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1303", section: "الرقائق", category: "الدعاء", level: "سهل", question: "ما الدعاء المأثور عند الاستيقاظ من النوم؟", answer: "«الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور» — رواه البخاري. أو: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير» عشراً.", explanation: "يُستفاد منه في باب الدعاء.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1304", section: "الرقائق", category: "الذكر والدعاء", level: "سهل", question: "بمَ أرشد النبي ﷺ فاطمة رضي الله عنها لمّا طلبت منه خادماً؟", answer: "قال لها ﷺ: «ألا أدلّك على ما هو خير لك من خادم؟ تسبّحين ثلاثاً وثلاثين، وتحمدين ثلاثاً وثلاثين، وتكبّرين أربعاً وثلاثين حين تأخذين مضجعك» (متفق عليه — رواه البخاري 3705 ومسلم 2727 عن علي بن أبي طالب).", explanation: "يُستفاد منه في باب الذكر والدعاء.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1305", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما أفضل صيغة للاستغفار وما تسمى؟", answer: "تسمى سيد الاستغفار: «اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شر ما صنعت، أبوء لك بنعمتك عليّ وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت».", explanation: "يُستفاد منه في باب التوبة والاستغفار.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1306", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما شروط التوبة الصحيحة من الذنب؟", answer: "ثلاثة شروط: 1- الإقلاع عن الذنب فوراً. 2- الندم على ما فات. 3- العزم على عدم العودة. وإن كان الذنب يتعلق بحق آدمي زُيد شرط رابع: رد الحقوق أو الاستحلال من أصحابها.", explanation: "يُستفاد منه في باب التوبة والاستغفار.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1307", section: "الرقائق", category: "التزكية", level: "سهل", question: "ما آفة اللسان التي حذّر منها النبي ﷺ حين سُئل عن أكثر ما يُدخل النار؟", answer: "الفم والفرج — قال ﷺ: «أكثر ما يُدخل الناسَ النار الأجوفان: الفم والفرج» (الترمذي ٢٠٠٤، صححه الألباني). واللسان مفتاح الفم ومدخل أعظم الذنوب.", explanation: "يُستفاد منه في باب التزكية.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1308", section: "الرقائق", category: "الزهد", level: "متوسط", question: "عرّف الزهد في الدنيا وما الفرق بينه وبين الفقر؟", answer: "الزهد: ترك ما لا ينفع في الآخرة وإيثار ما فيه رضا الله. وهو حال القلب لا المال؛ فقد كان سليمان ﷺ ذا ملك عظيم وهو زاهد، وقد يكون الفقير حريصاً غير زاهد.", explanation: "يُستفاد منه في باب الزهد.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1309", section: "الرقائق", category: "أمراض القلوب", level: "متوسط", question: "ما الكبر وما ضابطه عند أهل العلم؟", answer: "قال ﷺ: «الكبر: بطَر الحق وغمط الناس» (رواه مسلم). بطر الحق: رد الحق وعدم قبوله. غمط الناس: احتقارهم. وهو من الكبائر المهلكة للقلب.", explanation: "يُستفاد منه في باب أمراض القلوب.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1310", section: "الرقائق", category: "التوبة", level: "سهل", question: "ما أفضل وقت للاستغفار وما دليله من السنة؟", answer: "وقت الأسحار قُبيل الفجر — قال الله تعالى: ﴿وَالْمُسْتَغْفِرِينَ بِالْأَسْحَارِ﴾ (آل عمران: 17). وثبت في السنة نزول الرب تبارك وتعالى في كل ليلة إلى السماء الدنيا في الثلث الأخير.", explanation: "يُستفاد منه في باب التوبة.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1311", section: "الرقائق", category: "اليقين", level: "صعب", question: "ما الفرق بين الوسواس القهري الطبي وبين وسواس الشيطان الشرعي؟", answer: "وسواس الشيطان: خاطر إثمي عارض يُقاومه العبد بالذكر والاستعاذة ولا حرج فيه. والوسواس القهري الطبي: حالة مرضية تستدعي العلاج الطبي. وحكمهما يختلف: الأول مُمانَع شرعاً، والثاني مُعالَج طباً.", explanation: "يُستفاد منه في باب اليقين.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1312", section: "الرقائق", category: "التفكر", level: "سهل", question: "ما الساعات التي يُستحب فيها التفكر والتأمل في خلق الله؟", answer: "خير أوقاته بعد صلاة الفجر قبل شروق الشمس، وفي الليل. فقد نزلت عليه ﷺ ذات ليلة آيات ختام سورة آل عمران (في خلق السماوات والأرض واختلاف الليل والنهار) وقال: «لقد أُنزلت عليّ الليلة آيات، ويل لمن قرأها ولم يتفكر فيها» (رواه ابن حبان في صحيحه بإسناد صحيح على شرط مسلم).", explanation: "يُستفاد منه في باب التفكر.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1313", section: "الرقائق", category: "ذكر الموت", level: "متوسط", question: "ما الحديث الوارد في فضل ذكر الموت وكثرته؟", answer: "قال ﷺ: «أكثروا ذكر هاذم اللذات: الموت» (رواه الترمذي والنسائي، صحيح). والمعنى: قاطع اللذات وهادمها لأنه يُذكّر بزوال النعيم.", explanation: "يُستفاد منه في باب ذكر الموت.", reference: "رواه البخاري (6245) ومسلم (2153)" },
  { id: "1314", section: "الرقائق", category: "الخوف والرجاء", level: "متوسط", question: "هل يجوز اليأس من رحمة الله؟ ما حكمه؟", answer: "اليأس من رحمة الله كبيرة من الكبائر — قال الله تعالى: ﴿إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ﴾ (يوسف: 87). فاليأس من سمات الكافرين، والمؤمن يجمع الخوف والرجاء.", explanation: "يُستفاد منه في باب الخوف والرجاء.", reference: "رواه البخاري (6245) ومسلم (2153)" },
];

export const QA_ITEMS = [
  { id: "seed-qa-600", question: "ما حكم صلاة الجمعة؟", answer: "الجواب: صلاة الجمعة فرض على كل مسلم بالغ عاقل ذكر مقيم — قال ﷺ: «من ترك ثلاث جمع تهاوناً طبع الله على قلبه». رواه أبو داود (1052) وصححه الألباني. وهي ركعتان تُصلّى بعد الأذان الثاني.", category_id: "seed-cat-salah", ruling_type: "واجب", evidence: "", reference: "صحيح أبي داود 1052", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-601", question: "ما حكم صيام يوم عرفة؟", answer: "الجواب: صيام يوم عرفة لغير الحاج مستحب؛ قال ﷺ: «صيام يوم عرفة أحتسب على الله أن يكفر السنة التي قبله والتي بعده». رواه مسلم (1162). والحاج لا يصومه على الراجح.", category_id: "seed-cat-sawm", ruling_type: "مستحب", evidence: "", reference: "صحيح مسلم 1162", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصيام", slug: "sawm" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-602", question: "ما حكم الوصية لغير الوارث؟", answer: "الجواب: الوصية لغير الوارث جائزة بثلث المال فقط — {مِن بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَا أَوْ دَيْنٍ} — النساء: 11. ولا تُجاوز الثلث إلا برضا الورثة.", category_id: "seed-cat-fiqh", ruling_type: "جائز", evidence: "", reference: "سورة النساء: 11", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الفقه", slug: "fiqh" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-603", question: "ما حكم قراءة الفاتحة في الصلاة؟", answer: "الجواب: قراءة الفاتحة ركن في كل ركعة عند جمهور العلماء؛ قال ﷺ: «لا صلاة لمن لم يقرأ بفاتحة الكتاب». رواه البخاري (756) ومسلم (394).", category_id: "seed-cat-salah", ruling_type: "واجب", evidence: "", reference: "صحيح البخاري 756", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-604", question: "ما حكم النية في الوضوء؟", answer: "الجواب: النية شرط لصحة الوضوء عند جمهور العلماء — {وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ} — البينة: 5. ويُستحب تلفظها.", category_id: "seed-cat-tahara", ruling_type: "واجب", evidence: "", reference: "سورة البينة: 5", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الطهارة", slug: "tahara" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-605", question: "ما حكم الزكاة في الذهب؟", answer: "الجواب: زكاة الذهب واجبة إذا بلغ النصاب (85 جراماً) وحال عليه الحول — {وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ} — الأنعام: 141. ونسبتها 2.5%.", category_id: "seed-cat-zakat", ruling_type: "واجب", evidence: "", reference: "سورة الأنعام: 141", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الزكاة", slug: "zakat" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-606", question: "ما حكم صلاة العيد؟", answer: "الجواب: صلاة العيد سنة مؤكدة؛ قال ﷺ: «كان النبي ﷺ إذا كان يوم عيد أمر بإخراج الصبيان والنساء». رواه البخاري (912). وهي ركعتان.", category_id: "seed-cat-salah", ruling_type: "سنة", evidence: "", reference: "صحيح البخاري 912", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-607", question: "ما حكم التيمم؟", answer: "الجواب: التيمم بديل عن الوضوء والغسل عند عدم الماء أو العجز — {فَتَيَمَّمُوا صَعِيدًا طَيِّبًا} — المائدة: 6. ويُبطل بوجود الماء.", category_id: "seed-cat-tahara", ruling_type: "جائز", evidence: "", reference: "سورة المائدة: 6", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الطهارة", slug: "tahara" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-608", question: "ما حكم صيام يوم عاشوراء؟", answer: "الجواب: صيام يوم عاشوراء سنة؛ قال ﷺ: «صيام يوم عاشوراء أحتسب على الله أن يكفر السنة التي قبله». رواه مسلم (1162). ويُستحب صيام التاسع معه.", category_id: "seed-cat-sawm", ruling_type: "مستحب", evidence: "", reference: "صحيح مسلم 1162", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصيام", slug: "sawm" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-609", question: "ما حكم الحج على المسلم؟", answer: "الجواب: الحج واجب مرة في العمر على المستطيع — {وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ} — آل عمران: 97. والاستطاعة تشمل المال والبدن والأمن.", category_id: "seed-cat-hajj", ruling_type: "واجب", evidence: "", reference: "سورة آل عمران: 97", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الحج", slug: "hajj" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-610", question: "ما حكم قراءة القرآن في الركعة؟", answer: "الجواب: قراءة القرآن في الصلاة واجبة في الركعة الأولى على الأقل عند جمهور العلماء. ويُستحب قراءة سورة بعد الفاتحة.", category_id: "seed-cat-salah", ruling_type: "واجب", evidence: "", reference: "المغني — ابن قدامة", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-611", question: "ما حكم الربا؟", answer: "الجواب: الربا حرام بالاتفاق — {يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ} — البقرة: 276. ويشمل ربا الفضل وربا النسيئة.", category_id: "seed-cat-fiqh", ruling_type: "حرام", evidence: "", reference: "سورة البقرة: 276", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الفقه", slug: "fiqh" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-612", question: "ما حكم صلاة المسافر؟", answer: "الجواب: قصر الصلاة الرباعية للمسافر جائز — {وَإِذَا ضَرَبْتُمْ فِي الْأَرْضِ} — النساء: 101. ويُشترط أن يكون السفر مسافة القصر.", category_id: "seed-cat-salah", ruling_type: "جائز", evidence: "", reference: "سورة النساء: 101", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-613", question: "ما حكم الوتر؟", answer: "الجواب: الوتر سنة مؤكدة بعد العشاء — {وَأَقِمِ الصَّلَاةَ} — الإسراء: 78. ويُصلّى ركعة أو أكثر.", category_id: "seed-cat-salah", ruling_type: "سنة", evidence: "", reference: "سورة الإسراء: 78", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-614", question: "ما حكم صيام الست من شوال؟", answer: "الجواب: صيام ستّة أيام من شوال سنة — «من صام رمضان ثم أتبعه ستّاً من شوال كان كصيام الدهر». رواه مسلم (1164).", category_id: "seed-cat-sawm", ruling_type: "مستحب", evidence: "", reference: "صحيح مسلم 1164", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصيام", slug: "sawm" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-615", question: "ما حكم برّ الجيران؟", answer: "الجواب: برّ الجيران واجب — قال ﷺ: «ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه». رواه البخاري (6014) ومسلم (2624).", category_id: "seed-cat-adab", ruling_type: "واجب", evidence: "", reference: "صحيح البخاري 6014", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الآداب", slug: "adab" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-616", question: "ما حكم قراءة سورة الملك؟", answer: "الجواب: قراءة سورة الملك قبل النوم سنة — «إن سورة من القرآن ثلاثون آية شفعت لصاحبها». رواه الترمذي (2891) وصححه الألباني.", category_id: "seed-cat-quran", ruling_type: "مستحب", evidence: "", reference: "سنن الترمذي 2891", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "القرآن", slug: "quran" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-617", question: "ما حكم صلاة الاستسقاء؟", answer: "الجواب: صلاة الاستسقاء سنة عند القحط — قال ﷺ: «استسقوا الله». رواه البخاري (967). وهي ركعتان.", category_id: "seed-cat-salah", ruling_type: "مستحب", evidence: "", reference: "صحيح البخاري 967", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-618", question: "ما حكم الغسل من الجنابة؟", answer: "الجواب: الغسل من الجنابة واجب — {وَإِن كُنتُمْ جُنُبًا فَاطَّهَّرُوا} — المائدة: 6. وهو فرض قبل الصلاة.", category_id: "seed-cat-tahara", ruling_type: "واجب", evidence: "", reference: "سورة المائدة: 6", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الطهارة", slug: "tahara" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-619", question: "ما حكم صيام يوم الاثنين والخميس؟", answer: "الجواب: صيام يومي الاثنين والخميس سنة — «تُعرض الأعمال يوم الاثنين والخميس». رواه الترمذي (747) وصححه الألباني.", category_id: "seed-cat-sawm", ruling_type: "مستحب", evidence: "", reference: "سنن الترمذي 747", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصيام", slug: "sawm" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-620", question: "ما حكم إيتاء الزكاة؟", answer: "الجواب: إخراج الزكاة واجب — {خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً} — التوبة: 103. وتُخرج للمصارف الثمانية.", category_id: "seed-cat-zakat", ruling_type: "واجب", evidence: "", reference: "سورة التوبة: 103", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الزكاة", slug: "zakat" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-621", question: "ما حكم صلاة التراويح؟", answer: "الجواب: صلاة التراويح سنة في رمضان — «من قام رمضان إيماناً واحتساباً غُفر له ما تقدم من ذنبه». رواه البخاري (37).", category_id: "seed-cat-salah", ruling_type: "سنة", evidence: "", reference: "صحيح البخاري 37", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-622", question: "ما حكم قراءة آية الكرسي؟", answer: "الجواب: قراءة آية الكرسي بعد كل صلاة سنة — «من قرأ آية الكرسي دبر كل صلاة لم يمنعه من دخول الجنة إلا أن يموت». رواه النسائي (9928).", category_id: "seed-cat-quran", ruling_type: "مستحب", evidence: "", reference: "سنن النسائي 9928", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "القرآن", slug: "quran" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-623", question: "ما حكم صيام يوم عرفة للحاج؟", answer: "الجواب: صيام يوم عرفة للحاج مكروه عند جمهور العلماء؛ لأنه من شعائر الحج. ويُستحب للغير الحاج.", category_id: "seed-cat-sawm", ruling_type: "مكروه", evidence: "", reference: "المغني — ابن قدامة", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصيام", slug: "sawm" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-624", question: "ما حكم صلاة الجنازة؟", answer: "الجواب: صلاة الجنازة فرض كفاية — «من مات منكم فصلّوا عليه». رواه البخاري (1315). وهي أربع تكبيرات.", category_id: "seed-cat-salah", ruling_type: "واجب", evidence: "", reference: "صحيح البخاري 1315", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-625", question: "ما حكم سجود السهو؟", answer: "الجواب: سجود السهو واجب أو مستحب عند نقص أو زيادة في الصلاة — «إذا نسي أحدكم صلاته فليصلّها إذا ذكرها». رواه البخاري (597). ويُسجد قبل السلام أو بعده حسب نوع السهو.", category_id: "seed-cat-salah", ruling_type: "واجب", evidence: "", reference: "صحيح البخاري 597", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-626", question: "ما حكم صلاة الضحى؟", answer: "الجواب: صلاة الضحى سنة — «يصبح على كل سلامى من أحدكم: فليصلِّ أربعاً، فإن أراد أن يُوتَر عليه فليصلِّ ستاً». رواه مسلم (748). وهي ركعتان فأكثر بعد شروق الشمس.", category_id: "seed-cat-salah", ruling_type: "مستحب", evidence: "", reference: "صحيح مسلم 748", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-627", question: "ما حكم النفقة على الزوجة؟", answer: "الجواب: نفقة الزوجة واجبة على الزوج — {لِيُنفِقْ ذُو قُوَّةٍ مِنْهُ} — الطلاق: 6. وتشمل الطعام والكسوة والسكنى بقدر يساره.", category_id: "seed-cat-fiqh", ruling_type: "واجب", evidence: "", reference: "سورة الطلاق: 6", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الفقه", slug: "fiqh" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-628", question: "ما حكم صيام يوم عرفة؟", answer: "الجواب: صيام يوم عرفة لغير الحاج مستحب — «صيام يوم عرفة أحتسب على الله أن يكفر السنة التي قبله والتي بعده». رواه مسلم (1162).", category_id: "seed-cat-sawm", ruling_type: "مستحب", evidence: "", reference: "صحيح مسلم 1162", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصيام", slug: "sawm" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
  { id: "seed-qa-629", question: "ما حكم قراءة الفاتحة في الصلاة؟", answer: "الجواب: قراءة الفاتحة ركن في كل ركعة عند جمهور العلماء — «لا صلاة لمن لم يقرأ بفاتحة الكتاب». رواه البخاري (756) ومسلم (394).", category_id: "seed-cat-salah", ruling_type: "واجب", evidence: "", reference: "صحيح البخاري 756", status: "published", review_status: "approved", created_at: "2024-05-12T15:00:00.000Z", qa_categories: { name: "الصلاة", slug: "salah" }, trust_level: "scholarly_source", editorial_review_status: "unreviewed", last_updated_at: "2026-07-27T00:00:00.000Z" },
];

export const FAWAID_ITEMS = [
  { text: "ألا أنبئكم بخير أعمالكم وأزكاها عند مليككم… ذكر الله؛ فهو أخف على اللسان وأثقل في الميزان عند الرحمن. — فليُلزم المسلم العمل بما علم والدعوة إليه.", category: "الحديث", source: "الترمذي ٣٣٧٧ — صححه الألباني في صحيح الترغيب", author_name: "سنن الترمذي", status: "approved", verification_status: "verified" },
  { text: "من تعلم العلم ليباهي به العلماء ويجاري به السفهاء ويصرف به وجوه الناس إليه أدخله الله جهنم. — فليُلزم المسلم العمل بما علم والدعوة إليه. — فليُلزم المسلم العمل بما علم.", category: "طلب العلم", source: "رواه ابن ماجه (260) والترمذي (2654) — صححه الألباني", author_name: "سنن ابن ماجه", status: "approved", verification_status: "verified" },
  { text: "من أنفق نفقة في سبيل الله كُتبت له بسبعمائة ضعف، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الفقه", source: "رواه الترمذي (1625) والنسائي (3186) عن خريم بن فاتك الأسدي — حسّنه الترمذي وصححه الألباني", author_name: "سنن الترمذي", status: "approved", verification_status: "verified" },
  { text: "أفلا يتدبرون القرآن أم على قلوب أقفالها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما دلّ عليه الكتاب والسنة. — فليُلزم المسلم العمل بما علم.", category: "القرآن", source: "محمد: 24", author_name: "القرآن الكريم", status: "approved", verification_status: "verified" },
  { text: "ما يلفظ من قول إلا لديه رقيب عتيد، وهذا من فوائد العناية بلسان العرب وفهم كلام الله. كما دلّ عليه الكتاب والسنة. — فليُلزم المسلم العمل بما علم والدعوة إليه.", category: "اللغة", source: "ق: 18", author_name: "القرآن الكريم", status: "approved", verification_status: "verified" },
  { text: "من تواضع لله رفعه؛ فالرفعة ثمرة الخفض لله، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم", status: "approved", verification_status: "verified" },
  { text: "من صلى عليّ صلاة صلى الله عليه بها عشراً، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الحديث", source: "رواه مسلم", author_name: "صحيح مسلم", status: "approved", verification_status: "verified" },
  { text: "خذ من أموالهم صدقة تطهرهم وتزكيهم بها، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما دلّ عليه الكتاب والسنة. — فليُلزم المسلم العمل بما علم.", category: "الفقه", source: "التوبة: 103", author_name: "القرآن الكريم", status: "approved", verification_status: "verified" },
  { text: "الصوم جُنة؛ فإذا كان يوم صوم أحدكم فلا يرفث ولا يجهل، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الحديث", source: "متفق عليه", author_name: "صحيح البخاري", status: "approved", verification_status: "verified" },
  { text: "الحج مرة في العمر واجب على المستطيع، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الفقه", source: "وجوب الحج من آل عمران: 97، وتحديد المرة الواحدة من حديث «الحج مرة، فمن زاد فهو تطوع» — رواه أبو داود (1721) وابن ماجه (2886)، صححه الألباني", author_name: "القرآن الكريم والحديث النبوي", status: "approved", verification_status: "verified" },
  { text: "الصدقة تطفئ الخطيئة كما يطفئ الماء النار، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. — فليُلزم المسلم العمل بما علم والدعوة إليه. والدعوة إليه.", category: "الحديث", source: "الترمذي ٦١٤ — حسّنه الألباني", author_name: "سنن الترمذي", status: "approved", verification_status: "verified" },
  { text: "إن الله رفيق يحب الرفق في الأمر كله، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الدعوة", source: "رواه مسلم", author_name: "صحيح مسلم", status: "approved", verification_status: "verified" },
  { text: "تعاهدوا القرآن؛ فوالذي نفسي بيده لهو أشد تفلتاً من الإبل في عقلها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة.", category: "القرآن", source: "رواه البخاري ومسلم", author_name: "صحيح البخاري", status: "approved", verification_status: "verified" },
  { text: "أتدرون ما الغيبة؟ ذكرك أخاك بما يكره، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم", status: "approved", verification_status: "verified" },
  { text: "الحياء لا يأتي إلا بخير، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم. — فليُلزم المسلم العمل بما علم والدعوة إليه.", category: "الأخلاق", source: "رواه البخاري ومسلم", author_name: "صحيح البخاري", status: "approved", verification_status: "verified" },
  { text: "المرء على دين خليله فلينظر أحدكم من يخالل، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "التربية", source: "رواه أبو داود — حسنه الألباني", author_name: "سنن أبي داود", status: "approved", verification_status: "verified" },
  { text: "الدعاء بين الأذان والإقامة لا يرد، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — فليُلزم المسلم العمل بما علم.", category: "الفقه", source: "رواه أبو داود والترمذي — صححه الألباني في صحيح الترمذي", author_name: "سنن أبي داود", status: "approved", verification_status: "verified" },
  { text: "من قرأ آية الكرسي دبر كل صلاة لم يمنعه من دخول الجنة إلا أن يموت، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة.", category: "القرآن", source: "رواه النسائي — صححه الألباني في السلسلة الصحيحة (972)", author_name: "سنن النسائي", status: "approved", verification_status: "verified" },
  { text: "يريد الله بكم اليسر ولا يريد بكم العسر، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما دلّ عليه الكتاب والسنة. — فليُلزم المسلم العمل بما علم.", category: "الفقه", source: "البقرة: 185", author_name: "القرآن الكريم", status: "approved", verification_status: "verified" },
  { text: "الاستغفار سبب لدفع البلاء ونزول الرحمة، وهذا بيان يُعين على فهم مراد الله في كتابه. كما دلّ عليه الكتاب والسنة. — فليُلزم المسلم العمل بما علم والدعوة إليه.", category: "التفسير", source: "الأنفال: 33 — تفسير ابن كثير", author_name: "ابن كثير", status: "approved", verification_status: "verified" },
];

